  array['vegetarisch', 'taco', 'aardappel', 'Mexicaans']::text[],
  '[{"hoeveelheid": "300", "eenheid": "g", "naam": "kerstomaten"}, {"hoeveelheid": "100", "eenheid": "ml", "naam": "olijfolie"}, {"hoeveelheid": "0.25", "eenheid": "tl", "naam": "zeezout"}, {"hoeveelheid": null, "eenheid": null, "naam": "peper"}, {"hoeveelheid": "500", "eenheid": "g", "naam": "nieuwe aardappelen"}, {"hoeveelheid": "2", "eenheid": "el", "naam": "zonnebloemolie"}, {"hoeveelheid": "0.5", "eenheid": null, "naam": "rode ui (fijngehakt)"}, {"hoeveelheid": "3", "eenheid": "el", "naam": "peterselie (fijngehakt)"}, {"hoeveelheid": "1", "eenheid": null, "naam": "rode chilipeper (zonder zaadlijsten, in dunne ringetjes)"}, {"hoeveelheid": "8", "eenheid": null, "naam": "maïstortilla''s of bloemtortilla''s (verwarmd)"}, {"hoeveelheid": "15", "eenheid": null, "naam": "basilicumblaadjes (gehakt)"}, {"hoeveelheid": "125", "eenheid": "g", "naam": "belegen kaas (in blokjes)"}, {"hoeveelheid": "2", "eenheid": null, "naam": "avocado''s (in blokjes)"}]'::jsonb,
  array['Verwarm de oven voor op 200 °C. Schep de kerstomaten om met een deel van de olijfolie, spreid ze uit over een bakplaat en bestrooi ze met zout en peper. Rooster ze 15 tot 20 minuten tot ze zacht zijn.', 'Kook de aardappelen in ongeveer 15 minuten bijna gaar. Giet af, laat ze afkoelen, halveer ze en snijd ze in dunne plakjes.', 'Verhit de zonnebloemolie in een koekenpan op hoog vuur en bak de aardappelplakjes 2 tot 3 minuten tot ze kleur krijgen. Voeg de rode ui, peterselie en chilipeper toe, breng op smaak met zout en peper en bak nog een minuut.', 'Verwarm de tortilla''s. Schep het aardappelmengsel erop en werk af met de blokjes kaas, de avocado, de basilicum en de geroosterde tomaten.']::text[],
  'scraper', 'goedgekeurd', null
