select
  'Surf-and-turf taco''s van de barbecue met geroosterde ananas', 'Surf-and-turf taco''s van de barbecue met geroosterde ananas', 'delicious. magazine', 'https://deliciousmagazine.nl/koken/hoofdgerecht/surf-en-turf-bbq/', 4, 70, 'Mexicaans',
  array['taco', 'varkensvlees', 'vis', 'bbq', 'zomer', 'Mexicaans']::text[],
  '[{"hoeveelheid": "250", "eenheid": "g", "naam": "varkenshaas (vet eraf gesneden)"}, {"hoeveelheid": "1", "eenheid": "tl", "naam": "gemalen komijn"}, {"hoeveelheid": "1", "eenheid": "tl", "naam": "gemalen korianderzaad"}, {"hoeveelheid": "1", "eenheid": null, "naam": "teen knoflook (fijngeraspt)"}, {"hoeveelheid": "1", "eenheid": "tl", "naam": "gerookt paprikapoeder"}, {"hoeveelheid": "0.25", "eenheid": "tl", "naam": "chipotlepoeder"}, {"hoeveelheid": "0.5", "eenheid": null, "naam": "sinaasappel (rasp en sap)"}, {"hoeveelheid": "250", "eenheid": "g", "naam": "stevige visfilet (bijv. kingfish of albacore)"}, {"hoeveelheid": "0.25", "eenheid": null, "naam": "rode kool (flinterdun geschaafd)"}, {"hoeveelheid": "3", "eenheid": null, "naam": "limoenen (sap, plus partjes om erbij te serveren)"}, {"hoeveelheid": "1", "eenheid": null, "naam": "kleine ananas (geschild, in 8 parten)"}, {"hoeveelheid": "4", "eenheid": "el", "naam": "olijfolie"}, {"hoeveelheid": "2", "eenheid": null, "naam": "kleine rode uien (fijngesneden)"}, {"hoeveelheid": "0.25", "eenheid": null, "naam": "bosje koriander (fijngesneden, plus extra blaadjes)"}, {"hoeveelheid": "2", "eenheid": null, "naam": "avocado''s (geprakt)"}, {"hoeveelheid": null, "eenheid": null, "naam": "chilipoeder (naar smaak)"}, {"hoeveelheid": "8", "eenheid": null, "naam": "tortilla''s (gegrild)"}, {"hoeveelheid": null, "eenheid": null, "naam": "peper en zout"}]'::jsonb,
  array['Meng de varkenshaas met de komijn, koriander, knoflook, paprikapoeder, chipotlepoeder, de sinaasappelrasp en het sap, wat zout en peper. Laat 2 tot 3 uur afgedekt in de koelkast marineren.', 'Meng de rode kool met een deel van het limoensap en een snufje zout en peper en laat intrekken.', 'Maak de barbecue aan of verhit een grillpan. Bestrijk de ananasparten met olie en gril ze 6 tot 8 minuten tot ze schroeiplekjes hebben. Laat iets afkoelen, snijd ze in stukjes van 1,5 cm en meng met een fijngesneden rode ui, limoenrasp en -sap en de koriander tot een salsa.', 'Prak de avocado met de rest van de rode ui, 2 limoenen aan sap, zout en peper (en eventueel chilipoeder) tot guacamole.', 'Gril de varkenshaas 10 tot 12 minuten rondom gaar, laat 15 minuten rusten en snijd in plakjes. Wrijf de vis in met olie, zout en peper, gril 2 tot 3 minuten en laat 5 minuten rusten.', 'Zet alles in aparte kommen op tafel, met de gegrilde tortilla''s, limoenpartjes en extra koriander, en laat iedereen zijn eigen taco vullen.']::text[],
  'scraper', 'goedgekeurd', null
where not exists (select 1 from recepten where url = 'https://deliciousmagazine.nl/koken/hoofdgerecht/surf-en-turf-bbq/' and user_id is null);

