  'Taco''s met langzaam gestoofd rundvlees en chipotle', 'Taco''s met langzaam gestoofd rundvlees en chipotle', 'delicious. magazine', 'https://deliciousmagazine.nl/recepten/mexicaanse-tacos-con-carne-guisada/', 4, 230, 'Mexicaans',
  array['taco', 'rundvlees', 'stoofpot', 'Mexicaans']::text[],
  '[{"hoeveelheid": "100", "eenheid": "g", "naam": "chipotle in adobo (1 blikje)"}, {"hoeveelheid": "3", "eenheid": "el", "naam": "olie"}, {"hoeveelheid": "700", "eenheid": "g", "naam": "dikke runderlappen"}, {"hoeveelheid": "4", "eenheid": null, "naam": "grote rode uien"}, {"hoeveelheid": "3", "eenheid": "tl", "naam": "komijnzaad"}, {"hoeveelheid": "3", "eenheid": "tl", "naam": "gedroogde oregano"}, {"hoeveelheid": "3", "eenheid": null, "naam": "teentjes knoflook (in plakjes)"}, {"hoeveelheid": "4", "eenheid": null, "naam": "limoenen (het sap)"}, {"hoeveelheid": "1", "eenheid": null, "naam": "limoen (in dunne partjes)"}, {"hoeveelheid": null, "eenheid": null, "naam": "zure room"}, {"hoeveelheid": "2", "eenheid": null, "naam": "avocado''s (in blokjes)"}, {"hoeveelheid": "1", "eenheid": null, "naam": "bosje koriander (blaadjes geplukt)"}, {"hoeveelheid": "250", "eenheid": "g", "naam": "masa harina"}, {"hoeveelheid": null, "eenheid": null, "naam": "zout"}]'::jsonb,
  array['Verwarm de oven voor op 160 °C en pureer de chipotle met de adobosaus. Snijd 3 uien in dikke ringen en 1 ui in flinterdunne ringen.', 'Bak de runderlappen in delen snel bruin in een braadpan op hoog vuur en neem ze uit de pan. Bak in hetzelfde vet de dikke uienringen bruin, voeg komijn en knoflook toe en bak 2 minuten mee.', 'Doe het vlees terug in de pan met ongeveer driekwart van de chilipuree, de oregano, 1 tl zout en 400 ml water. Laat afgedekt 3,5 tot 4 uur in de oven garen en controleer af en toe of er nog genoeg vocht is.', 'Week de dunne uienringen intussen in het limoensap. Trek het mals gegaarde vlees met twee vorken uit elkaar, laat de saus zo nodig inkoken en schep er wat van door het vlees.', 'Maak de tortilla''s: kneed de masa harina met ongeveer 300 ml lauw water tot een zacht deeg, rol er balletjes ter grootte van een golfbal van en pers ze tussen plasticfolie plat. Bak ze in een hete droge koekenpan ongeveer 30 seconden, 1 minuut aan de andere kant en weer 30 seconden.', 'Beleg de warme tortilla''s met het vlees, wat saus, zure room, koriander, de ingelegde ui en avocado.']::text[],
  'scraper', 'goedgekeurd', null
where not exists (select 1 from recepten where url = 'https://deliciousmagazine.nl/recepten/mexicaanse-tacos-con-carne-guisada/' and user_id is null);

