eenheid": "g", "naam": "bloem"}, {"hoeveelheid": "2", "eenheid": "tl", "naam": "bakpoeder"}, {"hoeveelheid": "1", "eenheid": null, "naam": "snufje zout"}, {"hoeveelheid": "5", "eenheid": "tl", "naam": "zonnebloemolie"}, {"hoeveelheid": "140", "eenheid": "g", "naam": "verse spinazie"}, {"hoeveelheid": "200", "eenheid": "ml", "naam": "melk"}, {"hoeveelheid": "160", "eenheid": "g", "naam": "verse jalapeño''s"}, {"hoeveelheid": "40", "eenheid": "ml", "naam": "olijfolie (voor de jalapeño''s)"}, {"hoeveelheid": "80", "eenheid": "ml", "naam": "water (voor de gel)"}, {"hoeveelheid": "2.5", "eenheid": "g", "naam": "agar-agar"}, {"hoeveelheid": "80", "eenheid": "g", "naam": "zure room"}, {"hoeveelheid": "1", "eenheid": null, "naam": "citroen (het sap)"}, {"hoeveelheid": "12", "eenheid": null, "naam": "dun gesneden uienringen"}, {"hoeveelheid": "1", "eenheid": null, "naam": "krop botersla"}, {"hoeveelheid": "1", "eenheid": null, "naam": "pakje shisokers"}, {"hoeveelheid": "0.5", "eenheid": null, "naam": "zak Doritos Cool Ranch (tot poeder gemalen)"}]'::jsonb,
