enheid": null, "naam": "bos koriander (fijngesneden)"}, {"hoeveelheid": "2", "eenheid": null, "naam": "tomaten (grof gesneden)"}, {"hoeveelheid": "100", "eenheid": "ml", "naam": "passata"}, {"hoeveelheid": "100", "eenheid": "ml", "naam": "ciderazijn"}, {"hoeveelheid": "0.5", "eenheid": null, "naam": "komkommer (in blokjes)"}, {"hoeveelheid": "1", "eenheid": null, "naam": "grote tomaat (zonder zaadlijsten, in blokjes)"}, {"hoeveelheid": "1", "eenheid": null, "naam": "ui (voor de salsa)"}, {"hoeveelheid": "1", "eenheid": null, "naam": "rijpe avocado"}, {"hoeveelheid": "1", "eenheid": null, "naam": "limoen (het sap)"}, {"hoeveelheid": "16", "eenheid": null, "naam": "verse witte maïstortilla''s"}, {"hoeveelheid": null, "eenheid": null, "naam": "zonnebloemolie (om in te frituren)"}, {"hoeveelheid": "0.25", "eenheid": null, "naam": "witte kool (ragfijn geschaafd)"}, {"hoeveelheid": "1", "eenheid": null, "naam": "bosje lente-ui (fijngesneden)"}, {"hoeveelheid": null, "eenheid": null, "naam": "limoensap (naar smaak)"}, {"hoeveelheid": null, "eenheid": null, "naam": "peper en zout"}]'::jsonb,
